using UnityEngine;using UnityEditor;using System.IO;using BusinessAsUsual.Prototype;using BusinessAsUsual.FirstPerson;using BusinessAsUsual.Town;
internal class CommandScript:IRunCommand{public void Execute(ExecutionResult result){var lines=new System.Collections.Generic.List<string>{"name,passed"};foreach(var rect in new[]{TownMinimap.TownWorld,TownMinimap.MarketWorld}){var region=new TownMinimap.Region{world=rect};int i=0;foreach(var n in new[]{Vector2.zero,Vector2.one,new Vector2(.37f,.68f)}){var p=TownMinimap.World(region,n);lines.Add("roundtrip-"+rect.x+"-"+i+++","+(Vector2.Distance(n,TownMinimap.Normalized(region,p))<.00001f));}}
var c=TownMinimap.ClampMarker(new Vector2(-90,500),new Vector2(200,150),20);lines.Add("whole-icon-clamped,"+(c.x>=12&&c.y<=138));var guide=new TownGuidance();var target=new GameObject("Temporary marker target").AddComponent<BasicWorkstation>();target.transform.position=Vector3.zero;guide.objectives.Add(new TownObjective{id="active",target=target});guide.objectives.Add(new TownObjective{id="locked",target=target,active=false});guide.objectives.Add(new TownObjective{id="missing"});var r=new TownMinimap.Region{world=TownMinimap.TownWorld};lines.Add("locked-and-absent-filtered,"+(TownMinimap.ActiveMarkers(r,guide).Count==1));Object.DestroyImmediate(target.gameObject);lines.Add("destroyed-target-retires,"+(TownMinimap.ActiveMarkers(r,guide).Count==0));lines.Add("ambient-wrap-continuous,"+(Mathf.Abs(TownAtmosphere.Phase(10)-TownAtmosphere.Phase(610))<.00001f));File.WriteAllLines(Path.GetFullPath("../../Docs/Diagnostics/Phase7B/map-validation.csv"),lines);result.Log(string.Join("\n",lines));}}
